\label{theo:FSZ}
        If $(\Delta_n)_{n \in \mathbb{N}}$ is a countable family of infinite {normal} subgroups of $\Gamma$, then
        there is a free $\Gamma$-flow that is minimal as a $\Delta_n$-flow for all $n \in \mathbb{N}$.

\label{theo:main}
        If $(S_n)_{n \in \mathbb{N}}$ is a countable family of infinite subsets of $\Gamma$, then there exists a free $\Gamma$-flow 
        that is $S_n$-minimal for all $n \in \mathbb{N}$.

\label{corl:no_loc_fin}
        If $\Gamma$ has at most countably many infinite locally finite subgroups, then there exists a free $\Gamma$-flow 
        that is $\Delta$-minimal with respect to every infinite subgroup $\Delta \leqslant \Gamma$.

\label{theo:main_prime}
        If $(\mathcal{F}_n)_{n \in \mathbb{N}}$ is a sequence of unbounded families of finite subsets of $\Gamma$, then there exists a free $\Gamma$-flow 
        that is $\mathcal{F}_n$-minimal for all $n \in \mathbb{N}$.

\label{corl:subshift}\label{corl:subshift_prime}
        If $(\mathcal{F}_n)_{n \in \mathbb{N}}$ is a sequence of unbounded families of finite subsets of $\Gamma$, then there exists a free subflow of $2^\Gamma$
        that is $\mathcal{F}_n$-minimal for all $n \in \mathbb{N}$.

