Suppose $F \subset \Gamma$ is a finite set with $|F| \geqslant n$. Then $F$ has a $D$-spaced subset $R \subseteq F$ of size $|R| = r$ \cite[Lem.~4.1]{LLLDyn3}. 



Let $W \coloneqq DR$. Call a mapping $\varphi \colon W \to (k+1)$ \emphd{acceptable} if for each $1 \leqslant i \leqslant k$, there is $\sigma \in R$ such that
\begin{equation}\label{eq:acceptable}
    \varphi(\delta \sigma) \,=\, \begin{cases}
        i &\text{if } \delta = \mathbf{1},\\
        0 &\text{if } \delta \neq \mathbf{1},
    \end{cases} \qquad \text{for all }\delta \in D.
\end{equation}




Let $\mathcal{P} \subseteq k^W$ be the set of all acceptable maps $\varphi \colon W \to k$.

\begin{claim}\label{claim:bound_on_prob}
    $\displaystyle 1 - \frac{|\mathcal{P}|}{(k+1)^{|W|}} \,\leqslant\, k \left(1 - \frac{1}{(k+1)^d}\right)^r$.
\end{claim}
\begin{claimproof}
    We seek an upper bound on the probability that a uniformly random map $\varphi \colon W \to (k+1)$ is not acceptable. 
    The probability \eqref{eq:acceptable} holds for fixed $1 \leqslant i \leqslant k$ and a specific element $\sigma \in R$ is precisely $1/(k+1)^d$. Since the set $R$ is $D$-spaced, the conditions for different choices of $\sigma \in R$ are independent, so the probability \eqref{eq:acceptable} fails for some $1 \leqslant i \leqslant k$ and all $\sigma \in R$ is
    \[
        \left(1 - \frac{1}{(k+1)^d}\right)^r.
    \]
    Summing over all $1 \leqslant i \leqslant k$ yields the desired bound.
\end{claimproof}

